import{_ as l,C as o,o as r,c as s,j as i,E as n,a as e,a2 as h}from"./chunks/framework.C21TwvGF.js";const v=JSON.parse(`{"title":"1-hafta","description":"","frontmatter":{"title":"1-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"9-sinf (IoT)","link":"/9-sinf-iot/"},"n":1,"bob":"I-bob · IoT asoslari va virtual laboratoriya","lessons":[{"g":1,"title":"IoT tushunchasi va qo‘llanish sohalari","lead":"IoT tushunchasi va qo‘llanish sohalari","link":"/9-sinf-iot/hafta-01/dars-1","slide":"/slaydlar/9-sinf-iot/hafta-01/dars-1.html","test":"/slaydlar/9-sinf-iot/hafta-01/dars-1-test.html"},{"g":2,"title":"IoT arxitekturasi: Sensorlar, aktuatorlar va apparat ta'minoti","lead":"IoT arxitekturasi: Sensorlar, aktuatorlar va apparat ta'minoti","link":"/9-sinf-iot/hafta-01/dars-2","slide":"/slaydlar/9-sinf-iot/hafta-01/dars-2.html","test":"/slaydlar/9-sinf-iot/hafta-01/dars-2-test.html"},{"g":3,"title":"IoT arxitekturasi: Tarmoq, bulut va foydalanuvchi interfeysi","lead":"IoT arxitekturasi: Tarmoq, bulut va foydalanuvchi interfeysi","link":"/9-sinf-iot/hafta-01/dars-3","slide":"/slaydlar/9-sinf-iot/hafta-01/dars-3.html","test":"/slaydlar/9-sinf-iot/hafta-01/dars-3-test.html"}],"test":"/slaydlar/9-sinf-iot/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"9-sinf-iot/hafta-01/index.md","filePath":"9-sinf-iot/hafta-01/index.md"}`),u={name:"9-sinf-iot/hafta-01/index.md"},d={class:"blk"},m={id:"uyga-vazifa",tabindex:"-1"};function f(k,a,y,b,g,c){const t=o("Icon");return r(),s("div",null,[i("div",d,[i("h2",m,[n(t,{name:"house"}),a[0]||(a[0]=e(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=h('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h3 id="_1-dars-iot-tushunchasi-va-qo-llanish-sohalari" tabindex="-1">1-dars: IoT tushunchasi va qo‘llanish sohalari <a class="header-anchor" href="#_1-dars-iot-tushunchasi-va-qo-llanish-sohalari" aria-label="Permalink to &quot;1-dars: IoT tushunchasi va qo‘llanish sohalari&quot;">​</a></h3><ol><li>O&#39;zingiz yashayotgan xonadonda yoki maktabda IoT yordamida avtomatlashtirish mumkin bo&#39;lgan 2 ta muammoni aniqlang (masalan, chiroqni o&#39;chirishni unutish, gulni qachon sug&#39;orishni bilmaslik).</li><li>Ushbu muammolarni an&#39;anaviy yechim va IoT yechimi nuqtai nazaridan solishtirib bering.</li><li>Har bir tizim qaysi sohaga (Smart Home, Smart Agriculture, IIoT yoki Smart City) tegishli ekanini yozing.</li><li>Tizimda inson omilini kamaytirish (M2M — Machine to Machine tamoyili) qanday afzallik keltirishini 3 ta jumla bilan ifodalang.</li></ol><hr><h3 id="_2-dars-iot-arxitekturasi-sensorlar-aktuatorlar-va-apparat-ta-minoti" tabindex="-1">2-dars: IoT arxitekturasi: Sensorlar, aktuatorlar va apparat ta&#39;minoti <a class="header-anchor" href="#_2-dars-iot-arxitekturasi-sensorlar-aktuatorlar-va-apparat-ta-minoti" aria-label="Permalink to &quot;2-dars: IoT arxitekturasi: Sensorlar, aktuatorlar va apparat ta&#39;minoti&quot;">​</a></h3><ol><li>O&#39;zingiz o&#39;ylab topgan bitta IoT loyihasi (masalan, aqlli eshik qo&#39;ng&#39;irog&#39;i yoki aqlli akvarium) uchun zarur bo&#39;ladigan komponentlar ro&#39;yxatini tuzing: <ul><li>Kamida 2 ta sensor (analog va raqamli);</li><li>Kamida 2 ta aktuator (masalan, rele, motor, buzzer, ekran);</li><li>Bitta boshqaruvchi platasi (Arduino Uno yoki ESP32).</li></ul></li><li>Nima sababdan ushbu boshqaruvchi platasini tanlaganingizni asoslab bering (Wi-Fi kerakmi yoki oddiy hisoblash yetarlimi?).</li><li>Nima uchun 220V tokda ishlaydigan elektr asboblarini to&#39;g&#39;ridan-to&#39;g&#39;ri mikrokontroller piniga ulab bo&#39;lmasligini va bu yerda rele moduli qanday vazifani bajarishini tushuntiring.</li></ol><hr><h3 id="_3-dars-iot-arxitekturasi-tarmoq-bulut-va-foydalanuvchi-interfeysi" tabindex="-1">3-dars: IoT arxitekturasi: Tarmoq, bulut va foydalanuvchi interfeysi <a class="header-anchor" href="#_3-dars-iot-arxitekturasi-tarmoq-bulut-va-foydalanuvchi-interfeysi" aria-label="Permalink to &quot;3-dars: IoT arxitekturasi: Tarmoq, bulut va foydalanuvchi interfeysi&quot;">​</a></h3><ol><li>O&#39;z loyihangiz uchun eng ma&#39;qul simsiz aloqa texnologiyasini tanlang (Wi-Fi, Bluetooth Low Energy, LoRaWAN yoki Zigbee) va nima sababdan aynan shu texnologiya tanlanganini (masofa, quvvat sarfi, tezlik) tushuntiring.</li><li>Mikrokontrollerdan bulutga ma&#39;lumot uzatishda nima uchun HTTP emas, balki MQTT protokoli tavsiya etilishini 3 ta asosiy sabab bilan bayon qiling.</li><li>Foydalanuvchi mobil telefondagi Blynk (yoki shunga o&#39;xshash) dashboard orqali qanday ko&#39;rsatkichlarni ko&#39;rishi va qanday tugmalar orqali qurilmani boshqarishi mumkinligining sxematik eskizini chizing yoki matn ko&#39;rinishida tavsiflang.</li><li>Tizimda qaysi muhim qarorlar internetga qaramasdan Edge (lokal) darajasida, qaysilari esa Cloud (bulut) darajasida qabul qilinishini ajratib bering.</li></ol><hr>',11))])])}const T=l(u,[["render",f]]);export{v as __pageData,T as default};
